sys_script.script:
(function executeRule(current, previous) {
    var managerId = current.getValue('manager');

    // If no manager is assigned, no validation needed
    if (!managerId) {
        return;
    }

    // If the manager hasn't changed (on update), no validation needed
    if (previous && previous.getValue('manager') === managerId) {
        return;
    }

    // Check if another Dark Store already has this manager assigned
    var storeGr = new GlideRecord('x_2145749_qc_dark_store');
    storeGr.addQuery('manager', managerId);
    storeGr.addQuery('sys_id', '!=', current.getUniqueValue());
    storeGr.query();

    if (storeGr.hasNext()) {
        storeGr.next();
        var existingStore = storeGr.getDisplayValue('store_name');
        gs.addErrorMessage(
            'This Store Manager is already assigned to another Dark Store (' +
            existingStore +
            '). Each Store Manager can only manage one Dark Store.'
        );
        current.setAbortAction(true);
    }
})(current, previous);
